package controller;
import model.User;import util.DBConnection;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/invoice") public class InvoiceServlet extends HttpServlet{private String esc(String x){if(x==null)return "";return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}try{int id=Integer.parseInt(q.getParameter("bookingId"));try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT b.booking_id,b.pickup_date,b.return_date,b.total_amount,b.booking_status,c.car_name,c.brand,u.full_name,u.email,COALESCE((SELECT SUM(amount) FROM payments WHERE booking_id=b.booking_id AND payment_status='Paid'),0) paid FROM bookings b JOIN cars c ON c.car_id=b.car_id JOIN users u ON u.user_id=b.user_id WHERE b.booking_id=? AND b.user_id=?")){p.setInt(1,id);p.setInt(2,u.getUserId());try(ResultSet r=p.executeQuery()){if(!r.next()){s.sendError(404,"Invoice not found");return;}s.setContentType("text/html; charset=UTF-8");s.setHeader("Content-Disposition","attachment; filename=CarRentalPortal-Invoice-"+id+".html");PrintWriter o=s.getWriter();o.println("<!doctype html><html><head><meta charset='utf-8'><title>Car Rental Portal Invoice</title><style>body{font:16px Arial;max-width:760px;margin:40px auto;color:#172033}h1{color:#0755a5}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{font-size:22px;font-weight:bold}</style></head><body><h1>Car Rental Portal</h1><h2>Rental Invoice #"+id+"</h2><p>Customer: "+esc(r.getString("full_name"))+"<br>Email: "+esc(r.getString("email"))+"</p><table><tr><th>Car</th><td>"+esc(r.getString("brand"))+" "+esc(r.getString("car_name"))+"</td></tr><tr><th>Pickup</th><td>"+r.getDate("pickup_date")+"</td></tr><tr><th>Return</th><td>"+r.getDate("return_date")+"</td></tr><tr><th>Booking status</th><td>"+esc(r.getString("booking_status"))+"</td></tr><tr><th>Total rental amount</th><td>₹"+r.getBigDecimal("total_amount")+"</td></tr><tr><th>Paid amount</th><td>₹"+r.getBigDecimal("paid")+"</td></tr><tr><th>Balance</th><td>₹"+r.getBigDecimal("total_amount").subtract(r.getBigDecimal("paid"))+"</td></tr></table><p>Generated from Car Rental Portal booking records. This invoice is not a payment receipt unless the payment status confirms payment.</p><button onclick='window.print()'>Print / Save as PDF</button></body></html>");}}}catch(NumberFormatException e){s.sendError(400);}catch(SQLException e){throw new IOException("Unable to generate invoice",e);}}}
